using System.Text.Json.Nodes;
using GnOuGo.Flow.Core.Expressions;
using GnOuGo.Flow.Core.Parsing;
using GnOuGo.Flow.Core.Scripting;
using Xunit;

namespace GnOuGo.Flow.Tests.Expressions;

public sealed partial class ExpressionContractTests
{
    // Actual compiler output, generated by PureBranchesPreserveNullableValuesAndOnlyReachedChecks.
    [Theory]
    [InlineData(true, "  exact\ntext é ", true)]
    [InlineData(false, "", true)]
    [InlineData(true, "", false)]
    [InlineData(true, null, false)]
    public void ReadableBranchesKeepReachedChecksWithoutImportingUnrelatedObservations(bool authorized, string? label, bool success)
    {
        var measurements = new JsonArray();
        foreach (var bytes in new[] { 1, 1_200_000 })
        foreach (var warm in new[] { false, true })
        {
            string[]? expectedChecks = null; string? expectedFailure = null;
            foreach (var profile in new[] { "v13", "v14" })
            {
                using var stream = typeof(ExpressionContractTests).Assembly.GetManifestResourceStream(
                    "GnOuGo.Flow.Tests.Expressions.Fixtures.nullable-branch-" + profile + ".yaml")!;
                using var reader = new StreamReader(stream);
                var output = WorkflowParser.Parse(reader.ReadToEnd()).Workflows["main"].Outputs!["text"];
                var program = ExpressionSegments.Read(output.Expr!).Single().Expression;
                var context = new JsonObject { ["inputs"] = new JsonObject { ["authorized"] = authorized }, ["unusedObservation"] = new string('x', bytes) };
                if (label is not null) context["inputs"]!["label"] = label; // Test missing separately from the selected explicit-null branch.
                var allowance = new JintSandbox.MappingAllowance(10_000, TimeSpan.FromSeconds(5), 50_000_000);
                var events = new List<string>(); var evaluator = new ExpressionEvaluator();
                var start = System.Diagnostics.Stopwatch.GetTimestamp(); var allocated = GC.GetAllocatedBytesForCurrentThread();
                JsonNode? value = null;
                var error = Record.Exception(() => value = evaluator.EvaluateCheckedExpression(program, context,
                    output.ExpressionContracts![""]!.AsObject(), allowance, (_, origin, code) => events.Add(origin + ":" + (code ?? "passed"))));
                var measured = GC.GetAllocatedBytesForCurrentThread() - allocated;
                if (success)
                {
                    Assert.Null(error); Assert.Equal(authorized ? label : null, value?.GetValue<string>());
                }
                else
                {
                    var failure = Assert.IsType<WorkflowRuntimeException>(error);
                    var identity = failure.Code + ":" + failure.Details?["location"] + ":" + failure.Message;
                    if (expectedFailure is not null) Assert.Equal(expectedFailure, identity);
                    expectedFailure = identity;
                }
                if (expectedChecks is not null) Assert.Equal(expectedChecks, events);
                expectedChecks = events.ToArray();
                var counters = allowance.Snapshot();
                Assert.InRange(counters["materialized_bytes"]!.GetValue<long>(), 0, 20_000);
                counters["profile"] = profile; counters["unused_observation_bytes"] = bytes; counters["warm"] = warm;
                counters["allocated_bytes"] = measured; counters["elapsed_ms"] = System.Diagnostics.Stopwatch.GetElapsedTime(start).TotalMilliseconds;
                counters["checks"] = new JsonArray(events.Select(e => (JsonNode?)JsonValue.Create(e)).ToArray()); measurements.Add(counters);
            }
        }
        if (Environment.GetEnvironmentVariable("GNOU_GO_V14_RESOURCES") is { Length: > 0 } folder)
        {
            Directory.CreateDirectory(folder);
            File.WriteAllText(Path.Combine(folder, $"lexical-{authorized}-{label?.Length.ToString() ?? "missing"}.json"), measurements.ToJsonString(new() { WriteIndented = true }));
        }
    }
}
